<?= view('portal/partials/shell_start', ['pageTitle' => $quote['quote_number'], 'activeSection' => 'overview', 'businessName' => $businessName]) ?>
<a class="portal-back" href="/portal">&larr; Overview</a><header class="portal-record-heading"><div><p class="eyebrow">QUOTE</p><h1><?= esc($quote['quote_number']) ?></h1><p>Valid through <?= esc($quote['expires_on']) ?></p></div><span class="portal-status"><?= esc(\App\Models\QuoteModel::STATUSES[$quote['status']] ?? ucfirst($quote['status'])) ?></span></header>
<section class="portal-detail"><h2>Scope and pricing</h2><div class="portal-quote-table"><div class="portal-quote-row portal-quote-head"><span>Description</span><span>Quantity</span><span>Price</span><span>Total</span></div><?php foreach ($items as $item): ?><div class="portal-quote-row"><div><strong><?= esc($item['description']) ?></strong><?php if ($item['details']): ?><p><?= nl2br(esc($item['details'])) ?></p><?php endif ?></div><span data-label="Quantity"><?= esc(number_format((float) $item['quantity'], 2)) ?></span><span data-label="Price"><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $item['unit_price'], 2)) ?></span><strong data-label="Total"><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $item['line_total'], 2)) ?></strong></div><?php endforeach ?></div><dl class="portal-totals"><dt>Subtotal</dt><dd><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $quote['subtotal'], 2)) ?></dd><?php if ((float) $quote['discount_amount'] > 0): ?><dt>Discount</dt><dd>-<?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $quote['discount_amount'], 2)) ?></dd><?php endif ?><?php if ((float) $quote['tax_amount'] > 0): ?><dt>Tax</dt><dd><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $quote['tax_amount'], 2)) ?></dd><?php endif ?><dt class="total">Total</dt><dd class="total"><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $quote['total'], 2)) ?></dd><?php if ((float) $quote['deposit_percentage'] > 0): ?><dt>Deposit required</dt><dd><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $quote['deposit_amount'], 2)) ?></dd><?php endif ?></dl></section>
<?php if ($quote['terms'] || $quote['notes']): ?><section class="portal-detail portal-two-column"><?php if ($quote['terms']): ?><div><h2>Terms</h2><p><?= nl2br(esc($quote['terms'])) ?></p></div><?php endif ?><?php if ($quote['notes']): ?><div><h2>Notes</h2><p><?= nl2br(esc($quote['notes'])) ?></p></div><?php endif ?></section><?php endif ?>
<?php if ($quote['status'] === 'sent'): ?><section class="portal-callout"><div><strong>This quote is awaiting your decision.</strong><span>Open the secure proposal to accept or decline it.</span></div><a class="button button-primary" href="/proposal/<?= esc($quote['access_token'], 'attr') ?>">Review proposal</a></section><?php elseif ($quote['customer_response_note']): ?><section class="portal-detail"><h2>Your response note</h2><p><?= nl2br(esc($quote['customer_response_note'])) ?></p></section><?php endif ?>
